# include "MapMaster/CoreUtils/PropCPUResourceManagerUtils.hpp"

# include <stb_image.h>
# include <memory>

# include <assimp/Importer.hpp>
# include <assimp/config.h>
# include <stb_image.h>

using namespace MapMaster::CoreUtils::PropCPUResourceManagerUtils;

Texture Texture::FromFileHandles (Texture::FileUniquePtr diffuseFileHandle, Texture::FileUniquePtr alphaFileHandle) {
	if (nullptr == diffuseFileHandle) {
		return Texture::Dummy ();
	}
	else {
		int width = 0;
		int height = 0;
		int channels = 0;
		int desiredChannels = 3;

		if (nullptr != alphaFileHandle) {
			desiredChannels = 4;
		}

		unsigned char * pixels = stbi_load_from_file (
			diffuseFileHandle.get (),
			& width,
			& height,
			& channels,
			desiredChannels
		);

		if (nullptr != alphaFileHandle) {
			int alphaWidth = 0;
			int alphaHeight = 0;
			int alphaChannels = 0;

			unsigned char * alphaPixels = stbi_load_from_file (
				alphaFileHandle.get (),
				& alphaWidth,
				& alphaHeight,
				& alphaChannels,
				STBI_grey
			);

			for (int i = 0; i < width * height; i++) {
				// NOLINTNEXTLINE(cppcoreguidelines-pro-bounds-pointer-arithmetic,readability-math-missing-parentheses)
				pixels [i * 4 + 3] = alphaPixels [i];
			}

			stbi_image_free (alphaPixels);
		}

		return Texture::FromSTBI (width, height, desiredChannels, pixels);
	}
}

Mesh::Mesh (const std::string & path, int assimpPostProcessorSteps, unsigned int assimpImporterRemoveComponentFlags) : valid (true) {
	importer = std::make_shared <Assimp::Importer> ();
	importer->SetPropertyInteger (
		AI_CONFIG_PP_RVC_FLAGS,
		assimpImporterRemoveComponentFlags
	);

	scene = importer->ReadFile (path, assimpPostProcessorSteps);

	if (nullptr != scene) {
		valid = true;
	}
	else {
		Dummy d (assimpPostProcessorSteps, assimpImporterRemoveComponentFlags);
		* this = d;
	}
}

